('APX-S-3476-2', 'APX-C-3476', 2, null, null, null, null, 609, 545, 'Main Subject: A black lion with deep charcoal fur, a dense textured mane, powerful facial structure, expressive amber eyes, and extremely detailed whiskers. The lion wears a rich dark emerald grooming cape fastened around the neck.', null, null, null, null, null, 'comedic'),
('APX-S-3476-3', 'APX-C-3476', 3, null, null, null, null, 1155, 565, 'Clean focus pulls, precise autofocus on the lion’s eyes, mane texture, scissors, and comb. salon tools include a metal comb, mist spray bottle, professional shears, thinning scissors, and a dryer.', null, null, null, null, null, 'appetising'),
('APX-S-3476-4', 'APX-C-3476', 4, null, null, null, null, 1721, 612, 'Sequence: Opening: The black lion sits calmly in the styling chair wearing the emerald cape, mane slightly overgrown, fluffy, and uneven.', null, null, null, null, null, null),
('APX-S-3476-5', 'APX-C-3476', 5, null, null, null, null, 2334, 575, 'A comb lifts a section of the damp mane, and sharp professional scissors remove the excess in one clean, deliberate line. The trim feels precise and intentional, with crisp satisfying snips and visible chunks of dark fur falling away.', null, null, null, null, null, null),
('APX-S-3476-6', 'APX-C-3476', 6, null, null, null, null, 2910, 334, 'Warm air from a dryer pushes through the dark fur, making it billow and expand into the finished bowl shape. The strands dance in the airflow. Closing: The final perfectly round bowl-cut mane is revealed.', null, null, null, null, null, null),
